impl Settlement {
    /// Convert this user configuration into the runtime representation.
    pub fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::Settlement {
        actual::Settlement {
            offline: self.offline.parse(emitter),
            router: self.router.parse(emitter),
        }
    }
}

impl Offline {
    /// Convert optional Kagemusha proof-release cache controls into runtime parameters.
    pub fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::Offline {
        let Offline {
            kagemusha_release_policy_path,
            kagemusha_artifact_dir,
            kagemusha_catalog_qualification_seal_path,
            mut kagemusha_max_decoded_bytes,
        } = self;
        if kagemusha_release_policy_path.is_some() != kagemusha_artifact_dir.is_some() {
            emitter.emit(
                Report::new(ParseError::InvalidSettlementConfig).attach(
                    "settlement.offline.kagemusha_release_policy_path and settlement.offline.kagemusha_artifact_dir must be configured together",
                ),
            );
        }
        if kagemusha_catalog_qualification_seal_path.is_some()
            && (kagemusha_release_policy_path.is_none() || kagemusha_artifact_dir.is_none())
        {
            emitter.emit(
                Report::new(ParseError::InvalidSettlementConfig).attach(
                    "settlement.offline.kagemusha_catalog_qualification_seal_path requires both Kagemusha release paths",
                ),
            );
        }
        if kagemusha_release_policy_path
            .as_ref()
            .is_some_and(|path| path.as_os_str().is_empty())
            || kagemusha_artifact_dir
                .as_ref()
                .is_some_and(|path| path.as_os_str().is_empty())
            || kagemusha_catalog_qualification_seal_path
                .as_ref()
                .is_some_and(|path| path.as_os_str().is_empty())
        {
            emitter.emit(
                Report::new(ParseError::InvalidSettlementConfig)
                    .attach("settlement.offline Kagemusha release paths must not be empty"),
            );
        }
        if kagemusha_catalog_qualification_seal_path
            .as_ref()
            .is_some_and(|path| !path.is_absolute())
        {
            emitter.emit(Report::new(ParseError::InvalidSettlementConfig).attach(
                "settlement.offline.kagemusha_catalog_qualification_seal_path must be absolute",
            ));
        }
        if kagemusha_max_decoded_bytes == 0 {
            emitter.emit(Report::new(ParseError::InvalidSettlementConfig).attach(
                "settlement.offline.kagemusha_max_decoded_bytes must be greater than zero",
            ));
            kagemusha_max_decoded_bytes =
                defaults::settlement::offline::KAGEMUSHA_MAX_DECODED_BYTES;
        } else if kagemusha_max_decoded_bytes
            > defaults::settlement::offline::KAGEMUSHA_MAX_DECODED_BYTES
        {
            emitter.emit(Report::new(ParseError::InvalidSettlementConfig).attach(format!(
                "settlement.offline.kagemusha_max_decoded_bytes cannot exceed the non-raiseable {}-byte safety ceiling",
                defaults::settlement::offline::KAGEMUSHA_MAX_DECODED_BYTES
            )));
            kagemusha_max_decoded_bytes =
                defaults::settlement::offline::KAGEMUSHA_MAX_DECODED_BYTES;
        }
        actual::Offline {
            // Escrow bindings are deterministic runtime state. They are
            // populated lazily by offline instructions and are never supplied
            // by node configuration.
            escrow_accounts: BTreeMap::new(),
            kagemusha_release_policy_path,
            kagemusha_artifact_dir,
            kagemusha_catalog_qualification_seal_path,
            kagemusha_max_decoded_bytes,
        }
    }
}

impl Router {
    /// Convert router knobs into runtime parameters, validating guard rails.
    pub fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::Router {
        const MAX_EPSILON_BPS: u16 = 10_000;

        let Router {
            mut twap_window_seconds,
            mut epsilon_bps,
            buffer_alert_pct,
            buffer_throttle_pct,
            buffer_xor_only_pct,
            buffer_halt_pct,
            mut buffer_horizon_hours,
        } = self;

        if twap_window_seconds == 0 {
            emitter.emit(ParseError::InvalidSettlementConfig.into());
            twap_window_seconds = defaults::settlement::router::TWAP_WINDOW_SECS;
        }

        if epsilon_bps > MAX_EPSILON_BPS {
            emitter.emit(ParseError::InvalidSettlementConfig.into());
            epsilon_bps = defaults::settlement::router::EPSILON_BPS;
        }

        if buffer_horizon_hours == 0 {
            emitter.emit(ParseError::InvalidSettlementConfig.into());
            buffer_horizon_hours = defaults::settlement::router::BUFFER_HORIZON_HOURS;
        }

        let thresholds = (
            buffer_alert_pct,
            buffer_throttle_pct,
            buffer_xor_only_pct,
            buffer_halt_pct,
        );

        let resolved_thresholds = if Self::thresholds_valid(thresholds) {
            thresholds
        } else {
            emitter.emit(
                Report::new(ParseError::InvalidSettlementConfig)
                    .attach("buffer thresholds must satisfy alert > throttle > xor_only > halt"),
            );
            (
                defaults::settlement::router::ALERT_PCT,
                defaults::settlement::router::THROTTLE_PCT,
                defaults::settlement::router::XOR_ONLY_PCT,
                defaults::settlement::router::HALT_PCT,
            )
        };

        actual::Router {
            twap_window: Duration::from_secs(twap_window_seconds),
            epsilon_bps,
            buffer_alert_pct: resolved_thresholds.0,
            buffer_throttle_pct: resolved_thresholds.1,
            buffer_xor_only_pct: resolved_thresholds.2,
            buffer_halt_pct: resolved_thresholds.3,
            buffer_horizon_hours,
        }
    }

    fn thresholds_valid(thresholds: (u8, u8, u8, u8)) -> bool {
        let (alert, throttle, xor_only, halt) = thresholds;
        alert <= 100 && halt < xor_only && xor_only < throttle && throttle < alert && halt < 100
    }
}

