/// User-level configuration for serving untrusted apps on CID-derived origins.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct SorafsGatewayUntrustedHosting {
    /// Enable per-CID host routing.
    #[config(default = "defaults::sorafs::gateway::UNTRUSTED_HOSTING_ENABLED")]
    pub enabled: bool,
    /// Canonical live/test CID-host suffixes.
    #[config(nested)]
    pub cid_host_suffixes: SorafsGatewayCidHostSuffixes,
    /// Redirect path-gateway requests to the canonical CID host.
    #[config(default = "defaults::sorafs::gateway::PATH_GATEWAY_REDIRECT")]
    pub path_gateway_redirect: bool,
    /// Restrict canonical redirects to browser HTML navigations.
    #[config(default = "defaults::sorafs::gateway::REDIRECT_HTML_ONLY")]
    pub redirect_html_only: bool,
}

impl Default for SorafsGatewayUntrustedHosting {
    fn default() -> Self {
        Self {
            enabled: defaults::sorafs::gateway::UNTRUSTED_HOSTING_ENABLED,
            cid_host_suffixes: SorafsGatewayCidHostSuffixes::default(),
            path_gateway_redirect: defaults::sorafs::gateway::PATH_GATEWAY_REDIRECT,
            redirect_html_only: defaults::sorafs::gateway::REDIRECT_HTML_ONLY,
        }
    }
}

impl SorafsGatewayUntrustedHosting {
    fn parse(self) -> actual::SorafsGatewayUntrustedHosting {
        actual::SorafsGatewayUntrustedHosting {
            enabled: self.enabled,
            cid_host_suffixes: self.cid_host_suffixes.parse(),
            path_gateway_redirect: self.path_gateway_redirect,
            redirect_html_only: self.redirect_html_only,
        }
    }
}

/// User-level rolling-window rate limit configuration.
#[derive(Debug, ReadConfig, Clone, Copy, norito::JsonDeserialize)]
pub struct SorafsGatewayRateLimit {
    /// Maximum requests permitted within the rolling window.
    pub max_requests: Option<u32>,
    /// Duration of the rolling window.
    #[config(default = "defaults::sorafs::gateway::rate_limit::WINDOW")]
    pub window: Duration,
    /// Optional temporary ban duration applied after repeated violations.
    pub ban: Option<Duration>,
}

impl Default for SorafsGatewayRateLimit {
    fn default() -> Self {
        Self {
            max_requests: defaults::sorafs::gateway::rate_limit::MAX_REQUESTS,
            window: defaults::sorafs::gateway::rate_limit::WINDOW,
            ban: defaults::sorafs::gateway::rate_limit::BAN,
        }
    }
}

impl SorafsGatewayRateLimit {
    fn parse(self) -> actual::SorafsGatewayRateLimit {
        actual::SorafsGatewayRateLimit {
            max_requests: self
                .max_requests
                .or(defaults::sorafs::gateway::rate_limit::MAX_REQUESTS)
                .and_then(NonZeroU32::new),
            window: self.window,
            ban: self.ban.or(defaults::sorafs::gateway::rate_limit::BAN),
        }
    }
}

/// Challenge toggles for ACME automation.
#[derive(Debug, ReadConfig, Clone, Copy, norito::JsonDeserialize)]
pub struct SorafsGatewayAcmeChallenges {
    /// Solve DNS-01 challenges.
    #[config(default = "defaults::sorafs::gateway::acme::DNS01")]
    pub dns01: bool,
    /// Solve TLS-ALPN-01 challenges.
    #[config(default = "defaults::sorafs::gateway::acme::TLS_ALPN_01")]
    pub tls_alpn_01: bool,
}

impl Default for SorafsGatewayAcmeChallenges {
    fn default() -> Self {
        Self {
            dns01: defaults::sorafs::gateway::acme::DNS01,
            tls_alpn_01: defaults::sorafs::gateway::acme::TLS_ALPN_01,
        }
    }
}

impl SorafsGatewayAcmeChallenges {
    fn parse(self) -> actual::SorafsGatewayAcmeChallenges {
        actual::SorafsGatewayAcmeChallenges {
            dns01: self.dns01,
            tls_alpn_01: self.tls_alpn_01,
        }
    }
}

/// ACME automation configuration for SoraFS gateway certificates.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct SorafsGatewayAcme {
    /// Enable ACME automation.
    #[config(default = "defaults::sorafs::gateway::acme::ENABLED")]
    pub enabled: bool,
    /// Stable production handle reported by the injected ACME client.
    pub provider_handle: Option<String>,
    /// Non-zero deployed ACME adapter and public-policy revision.
    pub provider_revision: Option<u64>,
    /// Non-zero digest of the exact public ACME provider policy.
    pub provider_policy_digest_hex: Option<String>,
    /// Account email used for ACME registration.
    pub account_email: Option<String>,
    /// ACME directory URL.
    #[config(default = "defaults::sorafs::gateway::acme::directory_url()")]
    pub directory_url: String,
    /// Hostnames covered by the certificate order.
    #[config(default = "defaults::sorafs::gateway::acme::hostnames()")]
    pub hostnames: Vec<String>,
    /// Identifier of the DNS provider automation plug-in.
    pub dns_provider_id: Option<String>,
    /// Renewal window applied before expiry.
    #[config(default = "defaults::sorafs::gateway::acme::RENEWAL_WINDOW")]
    pub renewal_window: Duration,
    /// Backoff duration applied after failures.
    #[config(default = "defaults::sorafs::gateway::acme::RETRY_BACKOFF")]
    pub retry_backoff: Duration,
    /// Maximum jitter applied to retry scheduling.
    #[config(default = "defaults::sorafs::gateway::acme::RETRY_JITTER")]
    pub retry_jitter: Duration,
    /// Challenge toggles to exercise.
    #[config(nested)]
    pub challenges: SorafsGatewayAcmeChallenges,
    /// Initial ECH enabled state advertised via telemetry.
    #[config(default = "defaults::sorafs::gateway::acme::ECH_ENABLED")]
    pub ech_enabled: bool,
}

impl Default for SorafsGatewayAcme {
    fn default() -> Self {
        Self {
            enabled: defaults::sorafs::gateway::acme::ENABLED,
            provider_handle: None,
            provider_revision: None,
            provider_policy_digest_hex: None,
            account_email: defaults::sorafs::gateway::acme::account_email(),
            directory_url: defaults::sorafs::gateway::acme::directory_url(),
            hostnames: defaults::sorafs::gateway::acme::hostnames(),
            dns_provider_id: defaults::sorafs::gateway::acme::dns_provider_id(),
            renewal_window: defaults::sorafs::gateway::acme::RENEWAL_WINDOW,
            retry_backoff: defaults::sorafs::gateway::acme::RETRY_BACKOFF,
            retry_jitter: defaults::sorafs::gateway::acme::RETRY_JITTER,
            challenges: SorafsGatewayAcmeChallenges::default(),
            ech_enabled: defaults::sorafs::gateway::acme::ECH_ENABLED,
        }
    }
}

impl SorafsGatewayAcme {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::SorafsGatewayAcme {
        let provider = parse_sorafs_gateway_runtime_provider_binding(
            emitter,
            "sorafs.gateway.acme",
            "provider",
            self.enabled,
            self.provider_handle.as_deref(),
            self.provider_revision,
            self.provider_policy_digest_hex.as_deref(),
        );
        actual::SorafsGatewayAcme {
            enabled: self.enabled,
            provider,
            account_email: self.account_email,
            directory_url: self.directory_url,
            hostnames: self.hostnames,
            dns_provider_id: self.dns_provider_id,
            renewal_window: self.renewal_window,
            retry_backoff: self.retry_backoff,
            retry_jitter: self.retry_jitter,
            challenges: self.challenges.parse(),
            ech_enabled: self.ech_enabled,
        }
    }
}

/// One governed Ed25519 identity in the gateway compliance policy.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct SorafsGatewayComplianceSigner {
    /// Stable payload-free signer identifier.
    pub signer_id: String,
    /// Raw Ed25519 public key as 64 lowercase hexadecimal characters.
    pub public_key_hex: String,
}

/// One exact HTTPS host and its admitted TLS identities.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct SorafsGatewayComplianceFeedHost {
    /// Canonical lowercase DNS hostname.
    pub hostname: String,
    /// SHA-256 SPKI digests as 64 lowercase hexadecimal characters.
    #[config(default)]
    pub accepted_spki_sha256_hex: Vec<String>,
}

/// One authenticated external gateway compliance feed.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct SorafsGatewayComplianceFeed {
    /// Stable feed identifier.
    pub feed_id: String,
    /// Exact credential-free HTTPS URL.
    pub url: String,
    /// Require this feed in every promoted catalog.
    #[config(default = "true")]
    pub required: bool,
    /// Exact initial/redirect host allowlist.
    #[config(default)]
    pub hosts: Vec<SorafsGatewayComplianceFeedHost>,
}

/// Governed gateway compliance controller configuration.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct SorafsGatewayCompliance {
    /// Enable the signed durable controller.
    #[config(default = "defaults::sorafs::gateway::compliance::ENABLED")]
    pub enabled: bool,
    /// Stable production handle reported by the authenticated feed transport.
    pub feed_transport_provider_handle: Option<String>,
    /// Non-zero deployed feed-transport adapter and public-policy revision.
    pub feed_transport_provider_revision: Option<u64>,
    /// Non-zero digest of the exact configured hostname/SPKI policy.
    pub feed_transport_provider_policy_digest_hex: Option<String>,
    /// Absolute durable checkpoint file path.
    pub checkpoint_path: Option<PathBuf>,
    /// Non-zero governance policy identity as lowercase hexadecimal.
    pub policy_id_hex: Option<String>,
    /// Canonical regional identity for this independently administered gateway.
    pub region_id: Option<String>,
    /// Canonical gateway identity; must name one active configured gateway signer.
    pub gateway_id: Option<String>,
    /// Required distinct catalog approvals.
    #[config(default)]
    pub catalog_threshold: u16,
    /// Canonically signer-id-ordered catalog signers.
    #[config(default)]
    pub catalog_signers: Vec<SorafsGatewayComplianceSigner>,
    /// Canonically ordered revoked catalog signer identifiers.
    #[config(default)]
    pub revoked_catalog_signer_ids: Vec<String>,
    /// Required distinct regional-gateway acknowledgements.
    #[config(default)]
    pub gateway_ack_threshold: u16,
    /// Canonically signer-id-ordered regional-gateway identities.
    #[config(default)]
    pub gateway_signers: Vec<SorafsGatewayComplianceSigner>,
    /// Canonically ordered revoked regional-gateway signer identifiers.
    #[config(default)]
    pub revoked_gateway_signer_ids: Vec<String>,
    /// Canonically feed-id-ordered authenticated feeds.
    #[config(default)]
    pub feeds: Vec<SorafsGatewayComplianceFeed>,
    /// Maximum encoded feed response.
    #[config(default = "defaults::sorafs::gateway::compliance::MAX_ENCODED_BYTES")]
    pub max_encoded_bytes: Bytes<u64>,
    /// Maximum normalized/decompressed feed response.
    #[config(default = "defaults::sorafs::gateway::compliance::MAX_DECODED_BYTES")]
    pub max_decoded_bytes: Bytes<u64>,
    /// Maximum redirect count.
    #[config(default = "defaults::sorafs::gateway::compliance::MAX_REDIRECTS")]
    pub max_redirects: u8,
    /// Maximum distinct public DNS answers.
    #[config(default = "defaults::sorafs::gateway::compliance::MAX_DNS_ADDRESSES")]
    pub max_dns_addresses: usize,
    /// Per-connection feed timeout.
    #[config(default = "defaults::sorafs::gateway::compliance::CONNECT_TIMEOUT")]
    pub connect_timeout: Duration,
    /// Total feed operation timeout.
    #[config(default = "defaults::sorafs::gateway::compliance::TOTAL_TIMEOUT")]
    pub total_timeout: Duration,
    /// Maximum accepted timestamp skew.
    #[config(default = "defaults::sorafs::gateway::compliance::MAX_CLOCK_SKEW")]
    pub max_clock_skew: Duration,
    /// Maximum age of one source feed at catalog construction.
    #[config(default = "defaults::sorafs::gateway::compliance::MAX_FEED_AGE")]
    pub max_feed_age: Duration,
    /// Maximum signed catalog validity interval.
    #[config(default = "defaults::sorafs::gateway::compliance::MAX_CATALOG_VALIDITY")]
    pub max_catalog_validity: Duration,
    /// Maximum durable promotion/rollback history.
    #[config(default = "defaults::sorafs::gateway::compliance::MAX_HISTORY_ENTRIES")]
    pub max_history_entries: usize,
}

impl Default for SorafsGatewayCompliance {
    fn default() -> Self {
        Self {
            enabled: defaults::sorafs::gateway::compliance::ENABLED,
            feed_transport_provider_handle: None,
            feed_transport_provider_revision: None,
            feed_transport_provider_policy_digest_hex: None,
            checkpoint_path: None,
            policy_id_hex: None,
            region_id: None,
            gateway_id: None,
            catalog_threshold: 0,
            catalog_signers: Vec::new(),
            revoked_catalog_signer_ids: Vec::new(),
            gateway_ack_threshold: 0,
            gateway_signers: Vec::new(),
            revoked_gateway_signer_ids: Vec::new(),
            feeds: Vec::new(),
            max_encoded_bytes: defaults::sorafs::gateway::compliance::MAX_ENCODED_BYTES,
            max_decoded_bytes: defaults::sorafs::gateway::compliance::MAX_DECODED_BYTES,
            max_redirects: defaults::sorafs::gateway::compliance::MAX_REDIRECTS,
            max_dns_addresses: defaults::sorafs::gateway::compliance::MAX_DNS_ADDRESSES,
            connect_timeout: defaults::sorafs::gateway::compliance::CONNECT_TIMEOUT,
            total_timeout: defaults::sorafs::gateway::compliance::TOTAL_TIMEOUT,
            max_clock_skew: defaults::sorafs::gateway::compliance::MAX_CLOCK_SKEW,
            max_feed_age: defaults::sorafs::gateway::compliance::MAX_FEED_AGE,
            max_catalog_validity: defaults::sorafs::gateway::compliance::MAX_CATALOG_VALIDITY,
            max_history_entries: defaults::sorafs::gateway::compliance::MAX_HISTORY_ENTRIES,
        }
    }
}

impl SorafsGatewayCompliance {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> Option<actual::SorafsGatewayCompliance> {
        fn emit(emitter: &mut Emitter<ParseError>, message: impl Into<String>) {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(message.into()));
        }

        fn canonical_token(value: &str) -> bool {
            !value.is_empty()
                && value.len() <= 128
                && value.bytes().all(|byte| {
                    byte.is_ascii_lowercase()
                        || byte.is_ascii_digit()
                        || matches!(byte, b'.' | b'-' | b'_' | b':')
                })
        }

        fn parse_digest(
            emitter: &mut Emitter<ParseError>,
            path: &str,
            value: Option<&str>,
        ) -> Option<[u8; 32]> {
            let Some(value) = value else {
                emit(emitter, format!("{path} is required when enabled"));
                return None;
            };
            if value.len() != 64
                || !value
                    .bytes()
                    .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
            {
                emit(
                    emitter,
                    format!("{path} must be exactly 64 lowercase hexadecimal characters"),
                );
                return None;
            }
            let mut digest = [0_u8; 32];
            hex::decode_to_slice(value, &mut digest)
                .expect("validated lowercase 32-byte hexadecimal");
            if digest == [0; 32] {
                emit(emitter, format!("{path} must be nonzero"));
                return None;
            }
            Some(digest)
        }

        fn parse_signers(
            emitter: &mut Emitter<ParseError>,
            path: &str,
            signers: &[SorafsGatewayComplianceSigner],
        ) -> Vec<actual::SorafsGatewayComplianceSigner> {
            let mut parsed = Vec::with_capacity(signers.len());
            let mut previous: Option<&str> = None;
            let mut keys = BTreeSet::new();
            for (index, signer) in signers.iter().enumerate() {
                if !canonical_token(&signer.signer_id)
                    || previous.is_some_and(|value| value >= signer.signer_id.as_str())
                {
                    emit(
                        emitter,
                        format!("{path}[{index}].signer_id must be canonical and strictly ordered"),
                    );
                }
                let public_key = parse_digest(
                    emitter,
                    &format!("{path}[{index}].public_key_hex"),
                    Some(&signer.public_key_hex),
                );
                if let Some(public_key) = public_key {
                    if PublicKey::from_bytes(Algorithm::Ed25519, &public_key).is_err() {
                        emit(
                            emitter,
                            format!("{path}[{index}].public_key_hex is not a valid Ed25519 key"),
                        );
                    }
                    if !keys.insert(public_key) {
                        emit(emitter, format!("{path} public keys must be distinct"));
                    }
                    parsed.push(actual::SorafsGatewayComplianceSigner {
                        signer_id: signer.signer_id.clone(),
                        public_key,
                    });
                }
                previous = Some(&signer.signer_id);
            }
            parsed
        }

        fn validate_revocations(
            emitter: &mut Emitter<ParseError>,
            path: &str,
            revoked: &[String],
            signers: &[actual::SorafsGatewayComplianceSigner],
        ) {
            let mut previous: Option<&str> = None;
            for (index, signer_id) in revoked.iter().enumerate() {
                if !canonical_token(signer_id)
                    || previous.is_some_and(|value| value >= signer_id.as_str())
                    || !signers.iter().any(|signer| signer.signer_id == *signer_id)
                {
                    emit(
                        emitter,
                        format!(
                            "{path}[{index}] must be canonical, strictly ordered, and name a configured signer"
                        ),
                    );
                }
                previous = Some(signer_id);
            }
        }

        let feed_transport_provider = parse_sorafs_gateway_runtime_provider_binding(
            emitter,
            "sorafs.gateway.compliance",
            "feed_transport_provider",
            self.enabled,
            self.feed_transport_provider_handle.as_deref(),
            self.feed_transport_provider_revision,
            self.feed_transport_provider_policy_digest_hex.as_deref(),
        );

        if !self.enabled {
            if self.checkpoint_path.is_some()
                || self.policy_id_hex.is_some()
                || self.region_id.is_some()
                || self.gateway_id.is_some()
                || self.catalog_threshold != 0
                || !self.catalog_signers.is_empty()
                || !self.revoked_catalog_signer_ids.is_empty()
                || self.gateway_ack_threshold != 0
                || !self.gateway_signers.is_empty()
                || !self.revoked_gateway_signer_ids.is_empty()
                || !self.feeds.is_empty()
            {
                emit(
                    emitter,
                    "sorafs.gateway.compliance authority, feed, and checkpoint fields must be absent when disabled",
                );
            }
            return None;
        }

        let checkpoint_path = match self.checkpoint_path {
            Some(path)
                if path.is_absolute()
                    && path.file_name().is_some()
                    && !path.components().any(|component| {
                        matches!(
                            component,
                            std::path::Component::CurDir | std::path::Component::ParentDir
                        )
                    }) =>
            {
                Some(path)
            }
            _ => {
                emit(
                    emitter,
                    "sorafs.gateway.compliance.checkpoint_path must be an absolute file path without dot components",
                );
                None
            }
        };
        let policy_id = parse_digest(
            emitter,
            "sorafs.gateway.compliance.policy_id_hex",
            self.policy_id_hex.as_deref(),
        );
        let region_id = match self.region_id.as_deref() {
            Some(region_id) if canonical_token(region_id) => Some(region_id.to_owned()),
            _ => {
                emit(
                    emitter,
                    "sorafs.gateway.compliance.region_id must be one canonical non-secret identifier",
                );
                None
            }
        };
        let gateway_id = match self.gateway_id.as_deref() {
            Some(gateway_id) if canonical_token(gateway_id) => Some(gateway_id.to_owned()),
            _ => {
                emit(
                    emitter,
                    "sorafs.gateway.compliance.gateway_id must be one canonical non-secret identifier",
                );
                None
            }
        };
        let catalog_signers = parse_signers(
            emitter,
            "sorafs.gateway.compliance.catalog_signers",
            &self.catalog_signers,
        );
        let gateway_signers = parse_signers(
            emitter,
            "sorafs.gateway.compliance.gateway_signers",
            &self.gateway_signers,
        );
        validate_revocations(
            emitter,
            "sorafs.gateway.compliance.revoked_catalog_signer_ids",
            &self.revoked_catalog_signer_ids,
            &catalog_signers,
        );
        validate_revocations(
            emitter,
            "sorafs.gateway.compliance.revoked_gateway_signer_ids",
            &self.revoked_gateway_signer_ids,
            &gateway_signers,
        );
        if gateway_id.as_ref().is_some_and(|gateway_id| {
            !gateway_signers
                .iter()
                .any(|signer| signer.signer_id == *gateway_id)
                || self
                    .revoked_gateway_signer_ids
                    .binary_search(gateway_id)
                    .is_ok()
        }) {
            emit(
                emitter,
                "sorafs.gateway.compliance.gateway_id must name one active configured gateway signer",
            );
        }
        for (path, threshold, signers, revoked) in [
            (
                "catalog_threshold",
                self.catalog_threshold,
                &catalog_signers,
                &self.revoked_catalog_signer_ids,
            ),
            (
                "gateway_ack_threshold",
                self.gateway_ack_threshold,
                &gateway_signers,
                &self.revoked_gateway_signer_ids,
            ),
        ] {
            let active = signers.len().saturating_sub(revoked.len());
            if threshold == 0 || usize::from(threshold) > active {
                emit(
                    emitter,
                    format!(
                        "sorafs.gateway.compliance.{path} must be nonzero and not exceed active signer count"
                    ),
                );
            }
        }

        let mut feeds = Vec::with_capacity(self.feeds.len());
        let mut previous_feed: Option<&str> = None;
        for (feed_index, feed) in self.feeds.iter().enumerate() {
            if !canonical_token(&feed.feed_id)
                || previous_feed.is_some_and(|value| value >= feed.feed_id.as_str())
            {
                emit(
                    emitter,
                    format!(
                        "sorafs.gateway.compliance.feeds[{feed_index}].feed_id must be canonical and strictly ordered"
                    ),
                );
            }
            let mut hosts = Vec::with_capacity(feed.hosts.len());
            let mut previous_host: Option<&str> = None;
            for (host_index, host) in feed.hosts.iter().enumerate() {
                if host.hostname.is_empty()
                    || host.hostname != host.hostname.to_ascii_lowercase()
                    || previous_host.is_some_and(|value| value >= host.hostname.as_str())
                {
                    emit(
                        emitter,
                        format!(
                            "sorafs.gateway.compliance.feeds[{feed_index}].hosts[{host_index}].hostname must be lowercase and strictly ordered"
                        ),
                    );
                }
                let mut pins = Vec::with_capacity(host.accepted_spki_sha256_hex.len());
                for (pin_index, pin) in host.accepted_spki_sha256_hex.iter().enumerate() {
                    if let Some(pin) = parse_digest(
                        emitter,
                        &format!(
                            "sorafs.gateway.compliance.feeds[{feed_index}].hosts[{host_index}].accepted_spki_sha256_hex[{pin_index}]"
                        ),
                        Some(pin),
                    ) {
                        pins.push(pin);
                    }
                }
                if pins.is_empty() {
                    emit(
                        emitter,
                        format!(
                            "sorafs.gateway.compliance.feeds[{feed_index}].hosts[{host_index}] requires at least one SPKI pin"
                        ),
                    );
                }
                if !pins.windows(2).all(|pair| pair[0] < pair[1]) {
                    emit(
                        emitter,
                        format!(
                            "sorafs.gateway.compliance.feeds[{feed_index}].hosts[{host_index}] SPKI pins must be strictly ordered"
                        ),
                    );
                }
                hosts.push(actual::SorafsGatewayComplianceFeedHost {
                    hostname: host.hostname.clone(),
                    accepted_spki_sha256: pins,
                });
                previous_host = Some(&host.hostname);
            }
            if hosts.is_empty() {
                emit(
                    emitter,
                    format!(
                        "sorafs.gateway.compliance.feeds[{feed_index}] requires at least one HTTPS host"
                    ),
                );
            }
            feeds.push(actual::SorafsGatewayComplianceFeed {
                feed_id: feed.feed_id.clone(),
                url: feed.url.clone(),
                required: feed.required,
                hosts,
            });
            previous_feed = Some(&feed.feed_id);
        }
        if feeds.is_empty() {
            emit(
                emitter,
                "sorafs.gateway.compliance.feeds must not be empty when enabled",
            );
        }

        if self.max_encoded_bytes.0 == 0
            || self.max_encoded_bytes.0 > 16 * 1024 * 1024
            || self.max_decoded_bytes.0 == 0
            || self.max_decoded_bytes.0 > 16 * 1024 * 1024
            || self.max_redirects > 8
            || !(1..=32).contains(&self.max_dns_addresses)
            || self.connect_timeout.is_zero()
            || self.connect_timeout > Duration::from_secs(30)
            || self.total_timeout < self.connect_timeout
            || self.total_timeout > Duration::from_secs(120)
        {
            emit(
                emitter,
                "sorafs.gateway.compliance feed fetch bounds are invalid",
            );
        }
        if self.max_clock_skew > Duration::from_secs(3_600)
            || self.max_feed_age.is_zero()
            || self.max_feed_age > Duration::from_secs(30 * 24 * 60 * 60)
            || self.max_catalog_validity.is_zero()
            || self.max_catalog_validity > Duration::from_secs(30 * 24 * 60 * 60)
            || !(1..=4_096).contains(&self.max_history_entries)
            || [
                self.max_clock_skew,
                self.max_feed_age,
                self.max_catalog_validity,
            ]
            .iter()
            .any(|duration| duration.subsec_nanos() != 0)
        {
            emit(
                emitter,
                "sorafs.gateway.compliance freshness/history bounds are invalid",
            );
        }

        Some(actual::SorafsGatewayCompliance {
            checkpoint_path: checkpoint_path?,
            feed_transport_provider: feed_transport_provider?,
            policy_id: policy_id?,
            region_id: region_id?,
            gateway_id: gateway_id?,
            catalog_threshold: self.catalog_threshold,
            catalog_signers,
            revoked_catalog_signer_ids: self.revoked_catalog_signer_ids,
            gateway_ack_threshold: self.gateway_ack_threshold,
            gateway_signers,
            revoked_gateway_signer_ids: self.revoked_gateway_signer_ids,
            feeds,
            max_encoded_bytes: self.max_encoded_bytes,
            max_decoded_bytes: self.max_decoded_bytes,
            max_redirects: self.max_redirects,
            max_dns_addresses: self.max_dns_addresses,
            connect_timeout: self.connect_timeout,
            total_timeout: self.total_timeout,
            max_clock_skew: self.max_clock_skew,
            max_feed_age: self.max_feed_age,
            max_catalog_validity: self.max_catalog_validity,
            max_history_entries: self.max_history_entries,
        })
    }
}

#[cfg(test)]
mod sorafs_gateway_provider_config_tests {
    use super::*;

    #[test]
    fn enabled_acme_parses_one_exact_provider_binding() {
        let mut emitter = Emitter::new();
        let parsed = SorafsGatewayAcme {
            enabled: true,
            provider_handle: Some("hsm://gateway/acme/primary".to_owned()),
            provider_revision: Some(11),
            provider_policy_digest_hex: Some("71".repeat(32)),
            ..SorafsGatewayAcme::default()
        }
        .parse(&mut emitter);

        assert!(emitter.into_result().is_ok());
        let provider = parsed.provider.expect("enabled ACME provider binding");
        assert_eq!(provider.provider_handle, "hsm://gateway/acme/primary");
        assert_eq!(provider.revision, 11);
        assert_eq!(provider.policy_digest, [0x71; 32]);
    }

    #[test]
    fn enabled_acme_rejects_partial_provider_binding() {
        let mut emitter = Emitter::new();
        let parsed = SorafsGatewayAcme {
            enabled: true,
            provider_handle: Some("hsm://gateway/acme/primary".to_owned()),
            ..SorafsGatewayAcme::default()
        }
        .parse(&mut emitter);

        assert!(parsed.provider.is_none());
        assert!(emitter.into_result().is_err());
    }

    #[test]
    fn disabled_acme_and_compliance_reject_dormant_provider_bindings() {
        let mut acme_emitter = Emitter::new();
        let parsed = SorafsGatewayAcme {
            provider_handle: Some("hsm://gateway/acme/primary".to_owned()),
            provider_revision: Some(1),
            provider_policy_digest_hex: Some("71".repeat(32)),
            ..SorafsGatewayAcme::default()
        }
        .parse(&mut acme_emitter);
        assert!(parsed.provider.is_none());
        assert!(acme_emitter.into_result().is_err());

        let mut compliance_emitter = Emitter::new();
        let parsed = SorafsGatewayCompliance {
            feed_transport_provider_handle: Some(
                "sorafs.gateway.compliance.feed-https.v1".to_owned(),
            ),
            feed_transport_provider_revision: Some(1),
            feed_transport_provider_policy_digest_hex: Some("72".repeat(32)),
            ..SorafsGatewayCompliance::default()
        }
        .parse(&mut compliance_emitter);
        assert!(parsed.is_none());
        assert!(compliance_emitter.into_result().is_err());
    }
}

